public class Casting {
    public static void main(String[] args) {
        double price = 19.75;
        int rounded = (int) price;            // narrowing, explicit: truncates to 19

        int a = 10;
        double b = a;                          // widening, implicit

        Object obj = "a string";               // upcasting, implicit
        if (obj instanceof String) {
            String s = (String) obj;           // downcasting, explicit and safe here
            System.out.println(s.length());
        }
    }
}
